"use strict";(self.webpackChunkportfolio=self.webpackChunkportfolio||[]).push([[8214],{28453:(e,n,i)=>{i.d(n,{R:()=>c,x:()=>s});var t=i(96540);const o={},r=t.createContext(o);function c(e){const n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:c(e.components),t.createElement(r.Provider,{value:n},e.children)}},92441:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>s,default:()=>d,frontMatter:()=>c,metadata:()=>t,toc:()=>a});const t=JSON.parse('{"id":"technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/cSharp/readme","title":"C# Example","description":"Example","source":"@site/docs/technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/cSharp/readme.md","sourceDirName":"technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/cSharp","slug":"/technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/cSharp/","permalink":"/docs/technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/cSharp/","draft":false,"unlisted":false,"editUrl":"https://github.com/reshinto/reshinto.github.io/blob/dev/docs/technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/cSharp/readme.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Open Closed Principle (OCP)","permalink":"/docs/technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/"},"next":{"title":"JavaScript Example","permalink":"/docs/technologies/interviewPrep/design_principles/SOLID/OpenClosedPrinciple/javascript/"}}');var o=i(74848),r=i(28453);const c={},s="C# Example",l={},a=[];function p(e){const n={code:"code",h1:"h1",header:"header",pre:"pre",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"c-example",children:"C# Example"})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-csharp",children:'/*\nOpen Closed Principle\n\n- parts of the system or in the subsystems have to be open for extensions\n  - so you should be able to extend the functionality of a filter\n    - but should be closed for modification\n\n- shouldn\'t have to go back into the filter to modify things\n  - instead, to add functionality, should make new classes, implement ISpecifications, and feed those into something that has already been made and something that have already been shipped\n\n- should not reship the functionality of the filter to customers, but can ship additional modules, which implements an ISpecification and make use of better filter\n\n- the reason for doing this is because the code might already been shipped to the client\n*/\n\nusing System.Collections.Generic;\n\n// different colors of a product\npublic enum Color {\n  Red, Green, Blue\n}\n\npublic enum Size {\n  Small, Medium, Large, Huge\n}\n\npublic class Product {\n  public string name;\n  public Color color;\n  public Size size;\n\n  public Product(string name, Color color, Size size) {\n    if (name == null)\n      throw new System.ArgumentNullException(paramName: nameof(name));\n    this.name = name;\n    this.color = color;\n    this.size = size;\n  }\n}\n\n// filter products on website\n// NOT a good filter, do not use this class\npublic class ProductFilter {\n  public IEnumerable<Product> FilterBySize(IEnumerable<Product> products, Size size) {\n    foreach (var p in products) {\n      if (p.size == size)\n        yield return p;\n    }\n  }\n\n  // this needs to be added if not implemented, which is not good in this case\n  // by adding more methods here, it breaks the open closed principle\n  public IEnumerable<Product> FilterByColor(IEnumerable<Product> products, Color color) {\n    foreach (var p in products) {\n      if (p.color == color)\n        yield return p;\n    }\n  }\n\n  public static IEnumerable<Product> FilterBySizeAndColor(IEnumerable<Product> products, Size size, Color color)\n    {\n      foreach (var p in products)\n        if (p.size == size && p.color == color)\n          yield return p;\n    } // state space explosion\n}\n\n\n// SOLUTION, use inheritance and interfaces\n// implement by using the Specification pattern\npublic interface ISpecification<T> {\n  bool IsSatisfied(T t);  // check if criteria is statified\n}\n\n// make filter interface dynamic\npublic interface IFilter<T> {\n  IEnumerable<T> Filter(IEnumerable<T> items, ISpecification<T> spec);\n}\n\npublic class ColorSpecification : ISpecification<Product>\n{\n  private Color color;\n\n  public ColorSpecification(Color color)\n  {\n    this.color = color;\n  }\n\n  public bool IsSatisfied(Product p)\n  {\n    return p.color == color;\n  }\n}\n\npublic class SizeSpecification : ISpecification<Product> {\n  private Size size;\n\n  public SizeSpecification(Size size) {\n    this.size = size;\n  }\n\n  public bool IsSatisfied(Product p) {\n    return p.size == size;\n  }\n}\n\n// combinator\npublic class AndSpecification<T> : ISpecification<T>\n{\n  private ISpecification<T> first, second;\n\n  public AndSpecification(ISpecification<T> first, ISpecification<T> second)\n  {\n    this.first = first ?? throw new System.ArgumentNullException(paramName: nameof(first));\n    this.second = second ?? throw new System.ArgumentNullException(paramName: nameof(second));\n  }\n\n  public bool IsSatisfied(T t)\n  {\n    return first.IsSatisfied(t) && second.IsSatisfied(t);\n  }\n}\n\npublic class BetterProductFilter : IFilter<Product>\n  {\n    public IEnumerable<Product> Filter(IEnumerable<Product> items, ISpecification<Product> spec)\n    {\n      foreach (var i in items)\n        if (spec.IsSatisfied(i))\n          yield return i;\n    }\n  }\n\npublic class Program {\n  public static void Main() {\n    Product apple = new Product("Apple", Color.Green, Size.Small);\n    Product tree = new Product("Tree", Color.Green, Size.Large);\n    Product house = new Product("House", Color.Blue, Size.Large);\n\n    Product[] products = {apple, tree, house};\n\n    // not a good filter\n    ProductFilter pf = new ProductFilter();\n    System.Console.WriteLine("Green products (old):");\n    foreach (var p in pf.FilterByColor(products, Color.Green))\n      System.Console.WriteLine($" - {p.name} is green");\n\n    // better filter\n    BetterProductFilter bf = new BetterProductFilter();\n    System.Console.WriteLine("Green products (new):");\n    foreach (var p in bf.Filter(products, new ColorSpecification(Color.Green)))\n      System.Console.WriteLine($" - {p.name} is green");\n\n    System.Console.WriteLine("Large products");\n    foreach (var p in bf.Filter(products, new SizeSpecification(Size.Large)))\n      System.Console.WriteLine($" - {p.name} is large");\n\n    System.Console.WriteLine("Large blue items");\n    foreach (var p in bf.Filter(products,\n      new AndSpecification<Product>(new ColorSpecification(Color.Blue), new SizeSpecification(Size.Large)))\n    )\n    {\n      System.Console.WriteLine($" - {p.name} is big and blue");\n    }\n  }\n}\n'})})]})}function d(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(p,{...e})}):p(e)}}}]);